head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > headerMerge]<br/>Header Column 의 ID 두 개를 사용하여 Header Column 을 직사각형 병합합니다.",
    "validation" : [
        "startHeaderID(필수) 파라미터로 병합을 시작하려는 Header Column 의 ID 를 설정합니다. (병합하려는 영역의 좌상단)",
        "endHeaderID(필수) 파라미터로 병합을 종료하려는 Header Column 의 ID 를 설정합니다. (병합하려는 영역의 우하단)",
        "병합된 영역이 포함된 경우 메소드가 실행되지 않습니다.",
        "병합 성공 여부를 true/false 로 반환합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 생성 (가장 먼저)
    $c.gcm.createLabel('label="Header Column 은 column1 ~ column6 이며 디자인 병합이 없는 평범한 헤더입니다."', '', 'label1');

    // 기존 dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    // grp_comp 영역 / 네임스페이스 확인
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // DataList 생성 (col1~col6) 후 데이터 4행 setJSON 으로 채우고 gridView 에 바인딩
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    for (let c = 1; c <= 6; c++) {
        strData += '<w2:column id="col' + c + '" name="name' + c + '" dataType="text"></w2:column>';
    }
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [];
    for (let rIdx = 1; rIdx <= 4; rIdx++) {
        jsonData.push({ col1: "v" + rIdx + "_1", col2: "v" + rIdx + "_2", col3: "v" + rIdx + "_3", col4: "v" + rIdx + "_4", col5: "v" + rIdx + "_5", col6: "v" + rIdx + "_6" });
    }
    dlt_bind.setJSON(jsonData);

    // Header Column 6개(column1~column6) + Body 6컬럼 동적 생성 (디자인 병합 없음)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:600px;height:260px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column5" value="name5"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column6" value="name6"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col5" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col6" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 병합된 Header th 의 colspan / display 상태를 DOM 으로 확인 출력
scwin.printHeaderMergeState = function (startHeaderID) {
    let th = document.querySelector("th[data-header_id='" + startHeaderID + "'], th[header_id='" + startHeaderID + "']");
    if (th) {
        wf_body_bottom.getObj("scwin").setReturnValue("[" + startHeaderID + " th] colspan : " + (th.getAttribute("colspan") || "없음") + ", rowspan : " + (th.getAttribute("rowspan") || "없음"));
    }
    // 화면에 표시되는(display none 아닌) Header th 개수 = 병합 후 줄어든 헤더 셀 수
    let visibleThCnt = 0;
    let allTh = document.querySelectorAll("th[data-header_id], th[header_id]");
    for (let i = 0; i < allTh.length; i++) {
        if (allTh[i].style.display !== "none") visibleThCnt++;
    }
    wf_body_bottom.getObj("scwin").setReturnValue("화면 표시 Header th 개수 : " + visibleThCnt + " (병합 전 6개)");
}



// (validation #1, #2) startHeaderID, endHeaderID 로 직사각형 병합 실행
scwin.btn_headerMerge_onclick = function () {
    let start = par_startHeaderID.getValue();
    let end = par_endHeaderID.getValue();

    let result = target1.headerMerge(start, end);
    wf_body_bottom.getObj("scwin").setReturnValue("headerMerge('" + start + "', '" + end + "') : " + result);

    scwin.printHeaderMergeState(start);
}



// (validation #3, #4) 이미 병합된 영역이 포함된 범위로 재병합 → false 반환 + 미실행
scwin.btn_headerMerge_conflict_onclick = function () {
    // 시나리오 재현을 위해 기존 동적 헤더 병합 초기화
    target1.headerMergeClear();

    // 1차: column2 ~ column3 을 먼저 병합 (성공: true)
    let r1 = target1.headerMerge("column2", "column3");
    wf_body_bottom.getObj("scwin").setReturnValue("1차 headerMerge('column2', 'column3') : " + r1);
    scwin.printHeaderMergeState("column2");

    // 2차: 이미 병합된 영역(column2~column3)이 포함되는 범위(column3 ~ column4)로 재병합
    // → 병합된 영역이 포함된 경우이므로 false 반환 + 병합 미실행
    let r2 = target1.headerMerge("column3", "column4");
    wf_body_bottom.getObj("scwin").setReturnValue("2차 headerMerge('column3', 'column4') : " + r2 + " (병합된 영역 포함 → false, 미실행)");
    // column4 는 병합되지 않아 colspan 없음 (미실행 확인)
    scwin.printHeaderMergeState("column4");
}
